import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const root = process.cwd();
const expectedBranch = "gpt/phase1-region-registry";

const baselineHashes = {
  "src/app/api/imports/route.ts": "76da689e41f477a2b63d04d234d451d78ee6fc21f34e6b5aa5261b26b7042e39",
  "src/imports/client-preview.ts": "349922ac85883a4c0ce71b1240c06c39c82e086cb06be18ec71f5d22d4183f22",
  "src/components/ph-dashboard/ImportWorkspace.tsx": "542da643009178b87961a35d4e0cdf1ab3a32eb0f58895f0b489b8a94921e074",
  "src/imports/__tests__/client-preview.test.ts": "930f3b4b806318aaa4c9b975f1f43468de35861febbd2df92a9a53f4c9bd0fdf",
  "src/imports/contracts.ts": "d8e2249c839530557b789a2bbd6c92b98b60d08c751832b7d62aa95d1873d7de"
};
const encodedTargets = {"src/app/api/imports/route.ts":"","src/imports/client-preview.ts":"","src/imports/submission-contract.ts":"","src/components/ph-dashboard/ImportWorkspace.tsx":"","src/imports/__tests__/client-preview.test.ts":"","src/imports/__tests__/submission-contract.test.ts":"","src/imports/__tests__/submit-route-invariants.test.ts":""};
const newFiles = new Set([
  "src/imports/submission-contract.ts",
  "src/imports/__tests__/submission-contract.test.ts",
  "src/imports/__tests__/submit-route-invariants.test.ts",
]);

function projectPath(rel) {
  return path.join(root, rel);
}

function sha256Buffer(buffer) {
  return createHash("sha256").update(buffer).digest("hex");
}

function sha256File(file) {
  return sha256Buffer(fs.readFileSync(file));
}

function decodeTargets() {
  return new Map(
    Object.entries(encodedTargets).map(([rel, value]) => [
      path.resolve(projectPath(rel)),
      Buffer.from(value, "base64").toString("utf8"),
    ]),
  );
}

function run(command, args = []) {
  console.log(`\n> ${command} ${args.join(" ")}`);
  if (process.platform === "win32") {
    const comspec = process.env.ComSpec || process.env.COMSPEC || "C:\\Windows\\System32\\cmd.exe";
    execFileSync(comspec, ["/d", "/s", "/c", [command, ...args].join(" ")], {
      cwd: root,
      stdio: "inherit",
      shell: false,
      windowsHide: true,
    });
    return;
  }
  execFileSync(command, args, { cwd: root, stdio: "inherit", shell: false });
}

function readRequiredNextDocs() {
  const docs = [
    "node_modules/next/dist/docs/01-app/01-getting-started/05-server-and-client-components.md",
    "node_modules/next/dist/docs/01-app/01-getting-started/15-route-handlers.md",
  ];
  console.log("Read local Next.js docs required by AGENTS.md:");
  for (const rel of docs) {
    const file = projectPath(rel);
    if (!fs.existsSync(file)) throw new Error(`Required local Next.js doc not found: ${rel}`);
    fs.readFileSync(file, "utf8");
    console.log(`  ${rel}`);
  }
}

function verifyExactBaseline(targets) {
  for (const [rel, expected] of Object.entries(baselineHashes)) {
    const file = projectPath(rel);
    if (!fs.existsSync(file)) throw new Error(`Baseline file missing: ${rel}. No source was modified.`);
    const actual = sha256File(file);
    if (actual === expected) continue;
    const target = targets.get(path.resolve(file));
    if (target && actual === sha256Buffer(Buffer.from(target, "utf8"))) {
      console.log(`already patched: ${rel}`);
      continue;
    }
    throw new Error(
      `Baseline mismatch for ${rel}.\nExpected: ${expected}\nActual:   ${actual}\n` +
      "Source changed since the audit ZIP. No source was modified. Create a fresh audit ZIP rather than guessing."
    );
  }
  for (const rel of newFiles) {
    const file = projectPath(rel);
    if (!fs.existsSync(file)) continue;
    const target = targets.get(path.resolve(file));
    const expected = sha256Buffer(Buffer.from(target, "utf8"));
    const actual = sha256File(file);
    if (actual !== expected) throw new Error(`Unexpected existing file: ${rel}. No source was modified.`);
    console.log(`already patched: ${rel}`);
  }
}

function loadTypeScript() {
  try { return require(path.join(root, "node_modules", "typescript")); }
  catch { return require("typescript"); }
}

function formatDiagnostic(ts, diagnostic) {
  const message = ts.flattenDiagnosticMessageText(diagnostic.messageText, "\n");
  if (!diagnostic.file || diagnostic.start === undefined) return message;
  const pos = diagnostic.file.getLineAndCharacterOfPosition(diagnostic.start);
  return `${path.relative(root, diagnostic.file.fileName)}:${pos.line + 1}:${pos.character + 1} ${message}`;
}

function assertSyntax(ts, targets) {
  for (const [absolute, sourceText] of targets) {
    const sourceFile = ts.createSourceFile(
      absolute,
      sourceText,
      ts.ScriptTarget.Latest,
      true,
      absolute.endsWith(".tsx") ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
    );
    if (sourceFile.parseDiagnostics.length) {
      throw new Error(
        "In-memory syntax check failed before write:\n" +
        sourceFile.parseDiagnostics.map((d) => formatDiagnostic(ts, d)).join("\n"),
      );
    }
  }
}

function assertTargetInvariants(targets) {
  const route = targets.get(path.resolve(projectPath("src/app/api/imports/route.ts")));
  const client = targets.get(path.resolve(projectPath("src/imports/client-preview.ts")));
  const ui = targets.get(path.resolve(projectPath("src/components/ph-dashboard/ImportWorkspace.tsx")));
  const rawHash = route.indexOf('createHash("sha256")');
  const duplicateReturn = route.indexOf("return exactDuplicateResponse(duplicate);");
  const duplicateCode = route.indexOf('code: "EXACT_FILE_DUPLICATE"');
  const previewParse = route.indexOf("parseClientPreviewJson(previewText)");
  const previewHash = route.indexOf("computePreviewSha256(preview)");
  const storage = route.indexOf("storeImmutableArtifact(storageKey, bytes)");
  if (
    !(
      rawHash >= 0 &&
      duplicateReturn > rawHash &&
      previewParse > duplicateReturn &&
      previewHash > previewParse &&
      storage > previewHash &&
      duplicateCode >= 0
    )
  ) {
    throw new Error(
      "Target order invalid. Positions: " +
        JSON.stringify({
          rawHash,
          duplicateReturn,
          previewParse,
          previewHash,
          storage,
          duplicateCode,
        }),
    );
  }
  if (!route.includes("pg_advisory_xact_lock") || !route.includes("const concurrentDuplicate = await transaction.importBatch.findFirst")) {
    throw new Error("Target route is missing concurrent exact-duplicate serialization/recheck.");
  }
  if (!route.includes('code: "WORKBOOK_VALIDATION_FAILED"') || !route.includes('code: "NO_HOLIDAY_ROWS"') || !route.includes("previewHasBlockingErrors(preview)")) {
    throw new Error("Target route is missing backend blocking validation.");
  }
  if (!client.includes("GOVERNED_HOLIDAY_SCHEMA_VERSION") || !client.includes("LEGACY_HOLIDAY_SCHEMA_VERSION") || !client.includes("isSupportedClientPreviewSchemaVersion")) {
    throw new Error("Target client-preview parser is missing governed + legacy compatibility.");
  }
  const activeOverride = route.split("\n").filter((line) => !line.trimStart().startsWith("//") && line.includes('formData.get("confirmDuplicate")'));
  if (activeOverride.length) throw new Error("Retired confirmDuplicate override is active.");
  if (route.includes("Client preview schema is not supported.") || ui.includes("This exact workbook was imported before. Exact duplicate files cannot be reprocessed through the normal import flow.")) {
    throw new Error("Retired internal/user-facing wording remains in target source.");
  }
}

function assertInMemoryTypecheck(ts, targets) {
  const configPath = ts.findConfigFile(root, ts.sys.fileExists, "tsconfig.json");
  if (!configPath) throw new Error("tsconfig.json not found");
  const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
  if (configFile.error) throw new Error(formatDiagnostic(ts, configFile.error));
  const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, path.dirname(configPath));
  if (parsed.errors.length) throw new Error(parsed.errors.map((d) => formatDiagnostic(ts, d)).join("\n"));

  const rootNames = new Set(parsed.fileNames.map((f) => path.resolve(f)));
  for (const absolute of targets.keys()) rootNames.add(absolute);

  const host = ts.createCompilerHost(parsed.options, true);
  const originalFileExists = host.fileExists.bind(host);
  const originalReadFile = host.readFile.bind(host);
  const originalGetSourceFile = host.getSourceFile.bind(host);

  host.fileExists = (fileName) => targets.has(path.resolve(fileName)) || originalFileExists(fileName);
  host.readFile = (fileName) => targets.get(path.resolve(fileName)) ?? originalReadFile(fileName);
  host.getSourceFile = (fileName, languageVersion, onError, shouldCreateNewSourceFile) => {
    const absolute = path.resolve(fileName);
    const sourceText = targets.get(absolute);
    if (sourceText !== undefined) {
      return ts.createSourceFile(
        fileName,
        sourceText,
        languageVersion,
        true,
        absolute.endsWith(".tsx") ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
      );
    }
    return originalGetSourceFile(fileName, languageVersion, onError, shouldCreateNewSourceFile);
  };

  const program = ts.createProgram({ rootNames: [...rootNames], options: parsed.options, host });
  const diagnostics = ts.getPreEmitDiagnostics(program);
  if (diagnostics.length) {
    throw new Error(
      `Full in-memory project typecheck failed before write (${diagnostics.length} diagnostic(s)):\n` +
      diagnostics.slice(0, 60).map((d) => formatDiagnostic(ts, d)).join("\n"),
    );
  }
}

function backup(targets) {
  const result = new Map();
  for (const absolute of targets.keys()) result.set(absolute, fs.existsSync(absolute) ? fs.readFileSync(absolute) : null);
  return result;
}

function restore(backups) {
  for (const [absolute, content] of backups) {
    if (content === null) {
      if (fs.existsSync(absolute)) fs.unlinkSync(absolute);
    } else {
      fs.mkdirSync(path.dirname(absolute), { recursive: true });
      fs.writeFileSync(absolute, content);
    }
  }
}

function writeTargets(targets) {
  for (const [absolute, sourceText] of targets) {
    fs.mkdirSync(path.dirname(absolute), { recursive: true });
    fs.writeFileSync(absolute, sourceText, "utf8");
    console.log(`wrote ${path.relative(root, absolute)}`);
  }
}

const branch = execFileSync("git", ["branch", "--show-current"], { cwd: root, encoding: "utf8", shell: false }).trim();
if (branch !== expectedBranch) throw new Error(`Expected branch ${expectedBranch}, found ${branch}`);

console.log("== IMPORT SUBMIT BOUNDARY REPAIR V4.2 ==");
console.log("Self-contained package validated against the exact audit ZIP; no pattern-based source mutation");
readRequiredNextDocs();

const targets = decodeTargets();
verifyExactBaseline(targets);
const ts = loadTypeScript();

console.log("\nPre-write gate 1/3: TypeScript syntax");
assertSyntax(ts, targets);
console.log("passed");

console.log("Pre-write gate 2/3: submit-boundary invariants");
assertTargetInvariants(targets);
console.log("passed");

console.log("Pre-write gate 3/3: full project typecheck in memory");
assertInMemoryTypecheck(ts, targets);
console.log("passed");

const backups = backup(targets);
try {
  console.log("\nAll pre-write gates passed. Writing source...");
  writeTargets(targets);
  run("npm.cmd", ["run", "verify:fast"]);
  run("git", ["diff", "--check"]);
} catch (error) {
  console.error("\nPost-write verification failed. Restoring every touched file...");
  restore(backups);
  console.error("restore complete");
  throw error;
}

console.log("\n== IMPORT SUBMIT BOUNDARY REPAIR V4.2 PASSED ==");
console.log("governed 1.0 + legacy-1.0 accepted");
console.log("exact raw duplicate returns 409 before preview validation");
console.log("backend blocks empty/INVALID/ERROR previews");
console.log("concurrent same-file submissions are serialized and rechecked");
console.log("verify:fast + git diff --check passed");
console.log("\nManual smoke: governed new / legacy new / exact duplicate twice / unsupported schema / blocking errors / concurrent same-file submit");
